// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":95,"question":"يوجد لدينا في المستشفى مياه مجارٍ مُكررة، ونتعرض لتلك المياه في كثيرٍ من الأماكن من جراء ريِّ الحدائق، وقد نتعرض ولو لرذاذٍ منها، فهل تلك المياه نجسة تُبْطِل الوضوء؟ وهل الأشجار التي تُروى منها يجوز أكلُ ثمارها أم لا؟ أفيدونا جزاكم الله خيرًا","title":"ما حكم مياه المجاري المكرَّرة؟","answer":"الجواب: إذا كانت هذه المياه قد كُررت حتى ذهبتْ منها رائحةُ النَّجاسة وطعم النَّجاسة ولونها، وصارت مياهًا عذبةً طيبةً سليمةً؛ فلا حرج في ذلك، ويكون لها حكم الطَّهارة، وما يُصيب الناسَ منها لا يضرُّ، والشجر الذي يُسقى بها لا يضرُّ، وثمره لا بأس به.\nأمَّا إذا كانت آثارُ النجاسة باقيةً فيها فلا تُستعمل، لا في الأشجار، ولا في غيرها، بل تُزال إلى جهةٍ أخرى لا تُؤذي المسلمين.\nأمَّا إذا كانت كُررت تكريرًا كاملًا وزالت منها آثارُ النَّجاسة، في اللون، والطَّعم، والريح، فالحمد لله.","link":"https://binbaz.org.sa/fatwas/3123/ما-حكم-مياه-المجاري-المكررة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0074.mp3","categories":["المياه"]},{"id":1997,"question":"متى يكون الماء الراكد نَجِسًا؟","title":"متى يكون الماء الراكد نَجِسًا؟","answer":"الجواب:\nإذا تغيَّر بالنجاسة، أو كان قليلا جدًّا.\nس: إذا تغير أحد أوصافه الثلاث؟\nالشيخ: إذا تغير نَجُس وإن كان كثيرًا، وإذا كان قليلًا.....\nس: وإن كان أقل من القلتين؟\nالشيخ: محل نظر، قد يتنجس، وقد لا يتنجس، على الصحيح.\nس: الضابط الصحيح؟\nالشيخ: بعض أهل العلم يرى ما كان دون القلتين ينجس بمجرد الملاقاة، ولكن الصحيح أنه إذا كَثُر لا ينجس إلا بالتغير، أما الشيء القليل في الإناء مثل ما قال ﷺ، ما ولغ فيه الكلب فأرقه؛ لأن الأواني الصغيرة وقع فيها نجاسة تتأثر في الغالب؛ فالواجب إراقتها.","link":"https://binbaz.org.sa/fatwas/22113/متى-يكون-الماء-الراكد-نجسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون الماء الراكد نجسًا.mp3","categories":["المياه"]},{"id":4406,"question":"إذا كان أقلّ من قُلَّتين تقع فيه النَّجاسة؟","title":"حكم نجاسة الماء إذا كان أقلّ من قُلَّتين","answer":"الجواب: فيه الخلاف المذكور: من أهل العلم مَن يقول: إنه ينجس وإن لم يتغير.  وقول ثانٍ: لا ينجس إلا إذا تغير لونه أو ريحه أو طعمه.  إلا إذا كان قليلًا كمياه الأواني، فإن هذا يُراق، مثل: أمر النبي ﷺ بإراقة الإناء الذي ولغ فيه الكلب، الذي في الأواني يُراق؛ لأنَّ الغالب أنه تُؤثر فيه النَّجاسة؛ لأنه قليل.","link":"https://binbaz.org.sa/fatwas/24683/حكم-نجاسة-الماء-اذا-كان-اقل-من-قلتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نجاسة الماء إذا كان أقلّ من قُلَّتين.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":4407,"question":"الماء المغصوب؟","title":"هل تصح الطهارة بالماء المغصوب؟","answer":"الجواب: يحرم استعماله، الماء المغصوب مُحرَّم، لا لأجل أنه ما هو بطاهرٍ، هو طاهر، لكن ما يجوز؛ لأنك أخذتَه من صاحبه بغير حقٍّ.\nس: صحَّة الطَّهارة به؟\nج: الصحيح صحّة الطهارة؛ لأنَّ التحريم ما هو لأجل الطهارة، وإنما من أجل الظلم، مثلما تصحّ الصلاة على الأرض المغصوبة على الصحيح، لا لأنها جائزة، بل لأنَّ الطهارة تمت شروطها، لكن هو ظالم بغصبه إياها، واستيلائه عليها، وأخذه المال بغير حقٍّ، مطالب بهذا.\nس: استدلَّ المانعُ بحديث: إنَّ دماءكم وأموالكم وأعراضَكم عليكم حرام، فإن الطهارة لا تُجزئ؟\nج: حرام عليكم، لكن الطهارة صحيحة؛ لأنه ماء طهور توضأ به فأجزأه، لكنه ظالم بهذا، ولا تبطل الطهارة، كمَن صلَّى في الأرض المغصوبة؛ صحَّت صلاته وهو آثمٌ، المسألة خلافية، لكن هذا هو الأرجح.\nس: هو استدلَّ بهذا الحديث على عدم صحّة الطّهارة؟\nج: هذا يدل على التَّحريم فقط.","link":"https://binbaz.org.sa/fatwas/24684/هل-تصح-الطهارة-بالماء-المغصوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استعمال الماء المغصوب والطهارة به.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":4408,"question":"الترجمة الثانية: \"بَابُ الرَّدِّ عَلَى مَنْ جَعَلَ مَا يَغْتَرِفُ مِنْهُ الْمُتَوَضِّئُ بَعْدَ غَسْلِ وَجْهِهِ مُسْتَعْمَلًا\"؟","title":"حكم الماء الذي يغترف منه المتوضئ","answer":"الجواب: هذا حُجَّة على المؤلف.\nس: هذا ينافي ما قاله أولًا؟\nج: وهذا حُجَّة عليه؛ لأن إدخال يده في الإناء لا يجعله مستعملا، والنبي كان يدخل يديه أولا أدخلها في المضمضة والاستنشاق، ثم أدخلها لغسل وجهه، ثم أدخلها لغسل اليدين، إلى آخره.\nس: كيف الجمع بين هذا وهذا؟\nج: الجمع بأنَّ الماء ما زال في أعضاء الوضوء، فهو بحكم الطّهورية.\nس: فإذا انفصل؟\nج: فإذا انفصل صار إلى أنه طاهر دون طهور، وهذا دليلٌ على القول المشهور عند الحنابلة .. طاهر وطهور ونجس، وهو قول الشافعية وجماعة، والصواب أنه نوعان: طهور ونجس، والذي يُسمَّى: طاهرًا هو طهور، وإنما الطاهر فقط هي الجهة المضادة: كماء الورد، ماء الرمان، ماء العنب، هذه يُقال لها: ماء طاهرة فقط؛ لأنها مياه مُضاعفة مقيدة، ليست فيها مطلقة، أما الماء المطلق الذي قال الله فيه: فَلَمْ تَجِدُوا مَاءً [النساء:43]، فهذا حكمه الطّهارة، هذا الأصل، إلا إذا تغير بالنجاسة؛ صار نجسًا بالإجماع.\nس: ما يغترف منه المُتوضئ هذا طهور؟\nج: طاهر نعم، الطهورية باقية فيه ما دام تردد على الأعضاء، ولهذا يُزيل الأذى، الغسلة الأولى قد يكون هناك فيها شيء من أذى، ثم تأتي الثانية فتُزيل بقية الأذى، ثم تأتي الثالثة فتكمل، وكذلك ما قد يكون من نجاسةٍ في العضو، تُزيله الغسلة الأولى فتُخففه، ثم تأتي الثانية فتُخفف أو تُزيل، ثم تأتي الثالثة إلى أن تزول النّجاسة.","link":"https://binbaz.org.sa/fatwas/24685/حكم-الماء-الذي-يغترف-منه-المتوضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في حكم ما يغترف منه المتوضئ بعد غسل وجهه مستعملا.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":4411,"question":"مياه المجاري المُنقاة ..... التجارب؟","title":"ما الحكم في طهارة مياه المجاري المُنقاة؟","answer":"الجواب: إذا زال عنها الريحُ والطعمُ واللونُ لها حكم الطَّهارة.","link":"https://binbaz.org.sa/fatwas/24688/ما-الحكم-في-طهارة-مياه-المجاري-المنقاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طهارة مياه المجاري المُنقاة.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":4433,"question":"حكم الماء الراكد في الشمس؟","title":"حكم الماء المشمّس والبول في الماء الراكد","answer":"الجواب: ما في بأس، الشمس لا بأس، الماء المشمس فيه أخبار باطلة، ما هي صحيحة. كذلك البول في الماء الراكد يُنهى عنه، مثلما نهى النبيُّ ﷺ في حديث أبي هريرة عن البول في الماء الراكد؛ لأنَّ الماء الراكد يتأثر، فإذا بال فيه الناسُ تتابعت عليه الأبوال، وقد يتغير، فيكون نجسًا، فلهذا سدَّ النبي ﷺ الذَّريعة، ونهى عن البول في الماء الراكد؛ لئلا ينجر ذلك إلى تنجيسه وتقذيره.","link":"https://binbaz.org.sa/fatwas/24711/حكم-الماء-المشمس-والبول-في-الماء-الراكد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الماء الراكد في الشمس.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":5138,"question":"يقول هذا السائل: يوجد لدينا في المستشفى مياه مجارٍ مُكررة، ونتعرض لتلك المياه في كثيرٍ من الأماكن من جراء ريِّ الحدائق، وقد نتعرض ولو لرذاذٍ منها، فهل تلك المياه نجسة تُبْطِل الوضوء؟ وهل الأشجار التي تُروى منها يجوز أكلُ ثمارها أم لا؟ أفيدونا جزاكم الله خيرًا.","title":"ما حكم مياه المجاري المكررة؟","answer":"الجواب: إذا كانت هذه المياه قد كُررت حتى ذهبتْ منها رائحةُ النَّجاسة وطعم النَّجاسة ولونها، وصارت مياهًا عذبةً طيبةً سليمةً؛ فلا حرج في ذلك، ويكون لها حكم الطَّهارة، وما يُصيب الناسَ منها لا يضرُّ، والشجر الذي يُسقى بها لا يضرُّ، وثماره لا بأس به. أمَّا إذا كانت لا؛ آثارُ النجاسة باقيةً فيها فلا تُستعمل، لا في الأشجار، ولا في غيرها، بل تُزال إلى جهةٍ أخرى لا تُؤذي المسلمين. أمَّا إذا كانت كُررت تكريرًا كاملًا وزالت منها آثارُ النَّجاسة، لا لونًا، و لا طعمًا، ولا ريحًا، فالحمد لله.","link":"https://binbaz.org.sa/fatwas/30053/ما-حكم-مياه-المجاري-المكررة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 74.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":6626,"question":"هل الماء النجس إذا كرر وصفي بطرق علمية، هل هو طاهر، علمًا أن أصله نجس، وأن رائحته، ولونه، وطعمه كالماء الطبيعي الطاهر تمامًا؟","title":"حكم الماء النجس إذا صفي بطرق علمية","answer":"الجواب: إذا كان كثيرًا، ونقي بما فيه طهر، فإذا كان مثلًا غفيرًا كثيرًا، أصابته نجاسة غير بها طعمه، أو لونه، أو ريحه، ثم زالت زال التغير، وعاد إلى صفائه، وطيب رائحته، وطعمه؛ طهر بذلك. أما القليل الذي فيه النجاسة، ذهب ريحها؛ ما يضر القليل، لكن إذا كان كثيرًا إذا زال بالمعالجة، أو بغير المعالجة؛ زال الريح، والطعم، واللون؛ فإن الماء يعود طهورًا إذا كان كثيرًا، قلتين فأكثر، أما ما دون القلتين؛ فهو محل خلاف، والقليل جدًا هذا لا يطهر بكل حال، القليل النجاسة لا تزال فيه، ولو ذهب ريحها، أو طعمها، أو لونها، ولهذا أمر النبي ﷺ بإراقة الإناء الذي شرب منه الكلب؛ لأن في الغالب يتغير الأواني، ماؤها قليل، ولهذا أمر بإراقته.","link":"https://binbaz.org.sa/fatwas/2476/حكم-الماء-النجس-اذا-صفي-بطرق-علمية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1003.mp3","categories":["المياه","الآداب والأخلاق"]},{"id":6641,"question":"هل الماء النجس إذا كرر وصفي بطرق علمية، هل هو طاهر، علمًا أن أصله نجس، وأن رائحته، ولونه، وطعمه كالماء الطبيعي الطاهر تمامًا؟","title":"حكم الماء النجس إذا صفي بطرق علمية","answer":"الجواب: إذا كان كثيرًا، ونقي بما فيه طهر، فإذا كان مثلًا غفيرًا كثيرًا، أصابته نجاسة غير بها طعمه، أو لونه، أو ريحه، ثم زالت زال التغير، وعاد إلى صفائه، وطيب رائحته، وطعمه؛ طهر بذلك. أما القليل الذي فيه النجاسة، ذهب ريحها؛ ما يضر القليل، لكن إذا كان كثيرًا إذا زال بالمعالجة، أو بغير المعالجة؛ زال الريح، والطعم، واللون؛ فإن الماء يعود طهورًا إذا كان كثيرًا، قلتين فأكثر، أما ما دون القلتين؛ فهو محل خلاف، والقليل جدًا هذا لا يطهر بكل حال، القليل النجاسة لا تزال فيه، ولو ذهب ريحها، أو طعمها، أو لونها، ولهذا أمر النبي ﷺ بإراقة الإناء الذي شرب منه الكلب؛ لأن في الغالب يتغير الأواني، ماؤها قليل، ولهذا أمر بإراقته.","link":"https://binbaz.org.sa/fatwas/2476/حكم-الماء-النجس-اذا-صفي-بطرق-علمية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1003.mp3","categories":["المياه","الآداب والأخلاق"]},{"id":8107,"question":"رسالة وصلت إلينا من تهامة عسير باعثها أحد الإخوة من هناك يقول: ناصر يحيى طحطوح النجعي أخونا يسأل سؤال ويقول: ماء زمزم هل له تأثير على الرجل عندما يغتسل به أو لا؟","title":"حكم استعمال ماء زمزم في الاغتسال والاستنجاء","answer":"الجواب: ماء زمزم ماء مبارك، قال فيه النبي ﷺ في زمزم: إنها مباركة وقال فيها في مائها: إنه طعام طعم وشفاء سقم فهو ماء مبارك، ومن أسباب الشفاء من كثير من الأمراض، ولا مانع من أن يغتسل به المؤمن أو يتوضأ منه لا حرج، فقد توضأ منه النبي ﷺ، فإذا توضأ منه الإنسان أو اغتسل منه للتبرد أو للجنابة أو لما جعل الله فيه من البركة فلا حرج في ذلك، وله أن يستنجي منه أيضاً وله أن يستنجي منه أيضاً وإن كان مباركاً فلا مانع من الاستنجاء .. ماء طهور ماء طيب، فلا مانع من أن يستنجي منه كالماء الذي نبع من بين أصابعه ﷺ، فإن الماء نبع من بين أصابعه ﷺ مرات كثيرة، وهو من المعجزات الدالة على نبوته ﷺ وأنه رسول الله حقا، ومع ذلك أعطاه الصحابة حملوه في أوعيتهم يغتسلون ويستنجون ويتوضئون، وهو ماء عظيم مبارك، فهكذا ماء زمزم ماء عظيم مبارك، ولا حرج في الوضوء منه والاغتسال منه وإزالة النجاسة، ومن قال بكراهة ذلك من الفقهاء فقوله ضعيف مرجوح. نعم.","link":"https://binbaz.org.sa/fatwas/5903/حكم-استعمال-ماء-زمزم-في-الاغتسال-والاستنجاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_102/10202.mp3","categories":["المياه"]},{"id":8588,"question":"لها سؤال آخر الأخت (س. م. ع) من المدينة المنورة، تقول: ما حكم من وقع على ملابسها نجاسة أثناء تواجدها في مكان عام مثل المدرسة أو المستشفى وحضرت صلاة العصر وصلت ولم تعد إلى منزلها إلا بعد حضور صلاة المغرب، فأعادت صلاة العصر بعد صلاة المغرب، أفيدونا أفادكم الله؟","title":"حكم من وقع على ثوبه نجاسة ويريد الصلاة","answer":"الجواب: إذا وقع على ثياب الإنسان نجاسة وهو يعلم أنها نجاسة، ليس عن وسواس، بل يعلم أنها نجاسة فليس له أن يصلي حتى يغسلها، إذا كان عنده ماء، إذا استطاع الماء، ليس له أن يصلي حتى يغسل النجاسة، أما إن كان ظن وليس بجزم وإنما يظن أنها نجاسة ووسواس منه، هذا لا عمل عليه وليس فيه نجاسة، والأصل الطهارة، فإذا أصاب ثوب المرأة في المدرسة أو في أي مكان شيء رطب أو سقط عليها شيء فيه رطوبة فلا تحمله على النجاسة، الأصل الطهارة حتى تعلم أنه نجس، فإذا علمت ذلك يقيناً غسلته، والحمد لله.\nفإن لم تجد ماء بأن كانت في محل لا ماء فيه ولا تستطيع الخروج وتخشى خروج الوقت صلت ولا حرج عليها في ذلك، صلاتها صحيحة، فإذا استمرت ولم تصل إلا بعد الغروب إذا أحست بهذا وقت العصر، ولكنها أخرت حتى غابت الشمس فصلت المغرب ثم صلت العصر فهذا فيه تفصيل: إن كانت حين صلت المغرب قبل صلاة العصر ناسية أنها نجاسة أو شاكة فيها ثم علمت بعد ذلك فلا شيء عليها تعيد العصر والحمد لله؛ لأنها حين صلت المغرب ما عندها يقين أن صلاة العصر غير صحيحة، أما إن كانت ما صلت العصر بالكلية ثم صلت المغرب قبلها، هذا لا يصح لابد من أن تصلي العصر أول ثم تصلي المغرب، لكن إذا صلت العصر، ثم علمت أن في ثوبها نجاسة فإن صلاتها صحيحة، ولا تعيد الصلاة؛ لأن المسلم إذا صلى وفي ثوبه نجاسة جاهلاً بها لا يعلمها أو ناسياً لها فصلاته صحيحة؛ لأن النبي ﷺ صلى ذات يوم وفي نعليه أذى فأخبره جبرائيل عليه الصلاة والسلام بذلك، فخلع نعليه ولم يستأنف الصلاة ولم يعد أولها عليه الصلاة والسلام، فدل ذلك على أن الإنسان إذا صلى ثم علم أن في ثوبه نجاسة أو على بدنه نجاسة فلا إعادة عليه، ليس عليه إعادة، لأنه لم يعلم ذلك إلا بعد الصلاة.\nوالخلاصة: أن الإنسان إذا صلى المغرب أو العشاء أو غيرهما ثم ذكر أن عليه صلاة فإنه يأتي بالصلاة التي عليه ولا يعيد ما صلى، أما إذا تعمد أن يصلي المغرب وعليه صلاة العصر وهو يدري أن عليه صلاة العصر، أو تعمد يصلي العشاء وعليه صلاة المغرب قد علم ذلك هذا لا يجوز؛ لأن الترتيب واجب، إما إذا كان حين صلى المغرب أو العشاء قبل العصر أو قبل المغرب ناسياً أن عليه صلاة، أو جاهلاً أن عليه صلاة، فصلاته صحيحة، وليس عليه أن يعيد إلا الصلاة التي ثبت لديه أنها غير صحيحة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6667/حكم-من-وقع-على-ثوبه-نجاسة-ويريد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_209/20906.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":8666,"question":"غسل الملابس ومسح البلاط والمشي على السجاد الذي تبول عليه الأطفال؟الشيخ: غسل الملابس، وايش بعد؟المقدم: ومسح البلاط؟","title":"حكم المشي على السجاد الذي تبول عليه الأطفال للمتوضئ","answer":"الجواب: غسل الملابس تقدم هذا لا يضر، ومسح البلاط كذلك، إن كان فيه نجاسة تغسل ما أصاب يدها، إذا كانت الملابس نجسة تغسلها ثم تغسلها غسلاً يزيل أثر النجاسة به حسب الظن، تغسله مرتين ثلاث بالعصر تطهر وتطهر يدها مع ذلك، وغسل البلاط كذلك إن كان فيه نجاسة، تغسل البلاط ثم تغسل يديها من أثر البلاط غسلاً يزيل أثر النجاسة عن البلاط وعن يدها، مرتين تصب الماء مرتين ثلاث أربع حسب ما تظن أنه زال أثر النجاسة، وايش بعد غسل البلاط؟\nالمقدم: المشي على السجاد الذي سبق وتبول عليه الأطفال؟\nالشيخ: هذا فيه تفصيل: إن كان السجاد يابس والرجل يابسة أو في الكنادر ما تضر، فإن كانت الرجل رطبة أو الفراش رطب من البول تغسل رجلها إذا وطئت البول أو وطئت الفراش الذي فيه البول تغسل رجلها في محل آخر طاهر وينتهي الأمر.","link":"https://binbaz.org.sa/fatwas/6808/حكم-المشي-على-السجاد-الذي-تبول-عليه-الاطفال-للمتوضى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21413.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":8670,"question":"ملامسة ملابس الطفل المبتلة بالبول؟","title":"حكم لمس ملابس الطفل المبتلة بالبول بعد الوضوء","answer":"الجواب: إذا كان الطفل ملابسه مبتلة بالبول لا تلمسها فإن لمستها تغسل يدها، تغسل ما أصاب يدها من البول، والوضوء لا ينتقض.","link":"https://binbaz.org.sa/fatwas/6804/حكم-لمس-ملابس-الطفل-المبتلة-بالبول-بعد-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_214/21409.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":9197,"question":"أخ مستمع يمني مقيم بالمدينة المنورة يقول رضوان علي ثابت يسأل سؤالين:السؤال الأول يقول: عندنا في اليمن في قريتنا بركة يتوضأ منها الناس، والماء الذي فيها قد تغير لونه وطعمه، هل الوضوء صحيح أم لا؟ نرجو منكم التوجيه.","title":"حكم الوضوء في البرك إذا تغير لونها وطعمها","answer":"الجواب: إذا كانت البركة مصونة عن النجاسات وإنما تغيرها لطول المكث فلا يضر ذلك، أما إن كان يقع فيها نجاسات أو يستنجي الناس فيها عن الغائط والبول، ويكون ذلك يسقط فيها حتى تغير طعمها أو ريحها أو لونها بذلك فإنها تنجس، قد أجمع العلماء على أن الماء إذا تغير طعمه أو لونه أو ريحه بالنجاسة نجس، أما مجرد الوضوء منها من خارج كونه يتوضأ من خارج لا فيها، أو يتمسح مسوح فقط، يعني: يغسل وجهه ويديه من دون استنجاء هذا لا يضرها، ولو تغيرت بطول المكث كالمياه التي في البراري والصحاري فإن الأحواض التي في البراري والصحاري قد تتغير بالتراب وبالأوراق أوراق الشجر وغير هذا مما تلقيه الريح فلا يضر ذلك بل يكون الماء طهورًا سليمًا ولو تغير بهذه الأوراق أو بالتراب أو بغير ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7356/حكم-الوضوء-في-البرك-اذا-تغير-لونها-وطعمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18106.mp3","categories":["المياه"]},{"id":9434,"question":"يسأل أيضاً ويقول: ما حكم الشرع في أن يترك الرجل فراشه أو غطاء نومه لا يغسلهما عن النجاسات، بل يتركهما حتى ييبسا وهل تنجس الثياب إذا جلس عليها أحد من الناس؟","title":"حكم ترك الفرش والملابس دون تغسيل إذا أصابتها نجاسة","answer":"الجواب: ينبغي إذا أصاب الفراش نجاسة أن يغسل، وهكذا الرداء يغسل، وكذا الوسائد، لأن الإنسان قد يأتي إليها وعليه ملابس رطبة أو جسمه رطب فيتنجس بها، فالواجب أن تغسل وتطهر حتى إذا وطء عليها وأزيلت الرطبة أو جلس عليها بثوب رطب يسلم من شرها، أما إذا بقيت بالنجاسة ثم جلس عليها وهو رطب تنجس، فلا ينبغي هذا بل يجب على المؤمن أن يحذر ذلك، وأن يغسل ما يحتاج إليه من وطاء أو غطاء أو غير ذلك مما ينتفع به، فإذا كان قد اخلولق ولا حاجة إليه يلقى مع القمامة، أما يستعمله وهو نجس لا، يطهره أولاً ثم يستعمله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7603/حكم-ترك-الفرش-والملابس-دون-تغسيل-اذا-اصابتها-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23905.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":9730,"question":"السؤال الثالث في رسالة الأخ محمد بكري يقول فيه: أحيانًا تكون ثياب ابني الصغير مبللة بالنجاسة فيلمس بثيابه تلك دون شعور ثياب أخيه الكبير أو ثيابي ولكن آثار البلل لا تظهر على ثياب الكبير نتيجة الملامسة، فهل يلزم الكبير غسيل ثيابه لتطهيرها أما أنها لا تعتبر نجاسة لأنها لم تظهر عليه آثار البلل؟ وهل هناك طريقة للتطهير من النجاسة غير الغسيل كالتعريض للشمس مثلًا؟ وهل هناك سن يكون فيها بول الولد غير نجس أم أنه نجس منذ الولادة، أفيدونا أفادكم الله؟","title":"حكم بول الصبي","answer":"الجواب: بول الطفل نجس مطلقًا من حين الولادة إلى آخر حياته هو نجس لكنه في حالة الطفولة وعدم أكل الطعام تكون نجاسته مخففة يكفي فيها الرش والنضح حتى يأكل الطعام ويتغذى بالطعام، فإذا تغذى بالطعام صار يغسل لقول النبي ﷺ: بول الغلام ينضح وبول الجارية يغسل.\nفالمقصود أنه مادام لا يتغذى بالطعام بوله نجاسة خفيفة يجب فيها الرش والنضح، وإذا كان ثوب الصبي مبلل بالنجاسة ثم باشر ثوبًا آخر طاهر فإن هذا البلل ينجس الثوب الذي يلامسه؛ لأنه رطب إذا كان رطبًا، أما إذا كانت رطوبته خفيفة ما يؤثر في الثوب الذي يلامسه فلا بأس لا يتنجس لكن إذا كانت رطوبته واضحة وبينة فإنه لابد تؤثر في الثوب الذي تلامسه ولو ما بان ذلك بينونة ظاهرة فينبغي غسل ما أصاب الثوب الجديد الطاهر من هذا البلل يتحراه ويغسله بالماء وليس هناك طريق غير الماء، الشمس ما تكفي، لابد من غسله بالماء ولهذا كان النبي إذا أصابه بول الصبي صب عليه الماء عليه الصلاة والسلام، وإذا كان صغيرًا أتبعه بالماء ولم يعصره ولم يغسله بل يكفي رشه بالماء كما تقدم.","link":"https://binbaz.org.sa/fatwas/7885/حكم-بول-الصبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_195/19510.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":9895,"question":"ما حكم الصلاة في ثوب فيه نجاسة يقول: مع علمي بذلك، هل تصح صلاتي في مثل هذه الحالة؟","title":"حكم الصلاة في ثوب فيه نجاسة","answer":"الجواب: لا يجوز أن يصلي في ثوب فيه نجاسة، لابد يزيل النجاسة بالغسل، أو يبد له أما لو صلى ناسيًا أو جاهلًا ، ولم يعلم إلا بعد الصلاة فالصلاة صحيحة.","link":"https://binbaz.org.sa/fatwas/8063/حكم-الصلاة-في-ثوب-فيه-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27307.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":10115,"question":"الطالب عبدالله محمود طاهر بعث يسأل ويقول: إذا اكتشفت في أن أحد ملابسي شيئًا من النجاسة فهل أعيد ما صليت في تلك الملابس؟","title":"حكم من اكتشف بعد الصلاة أن في ثيابه نجاسة","answer":"الجواب: لا، لا تلزمك الإعادة، إذا وجد الإنسان في ثيابه أو في سراويله أو نحو ذلك نجاسة بعد الصلاة فإنه لا يعيدها، وهكذا لو كان يعلم ثم نسي حتى فرغ من الصلاة لا يعيد على الصحيح؛ لأن الرسول ﷺ في بعض صلواته نبهه جبرائيل قال: إن في نعليك قذرًا، فخلعهما عليه الصلاة والسلام ولم يعد أول الصلاة، فدل ذلك على أنه لا تعاد إذا صلاها وهو جاهل أو ناسي ولم يعلم إلا بعد الفراغ فإنه لا يعيد، هذا هو الصواب. إذا سلم ثم علم أن في إزاره أو قميصه أو سراويله أو بشته نجاسة ولم يعلم إلا بعد الفراغ فإن صلاته صحيحة، هذا هو الصواب، بخلاف الحدث، أما الحدث يعيد، لو صلى يظن أنه على طهارة ثم لما فرغ علم أنه ليس على طهارة وأنه قد أحدث ريح أو بول أو غير ذلك فإنه يعيد الصلاة عند أهل العلم؛ لقوله ﷺ: لا تقبل صلاة بغير طهور فلا تقبل الصلاة إلا بطهارة، أما النجاسة التي في الثوب فلها حكم آخر، النجاسة في الثوب أو في البشت أو في النعل أو نحو ذلك إذا لم يعلم إلا بعد الصلاة صلاته صحيحة، هذا هو المعتمد هذا هو الصواب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8286/حكم-من-اكتشف-بعد-الصلاة-ان-في-ثيابه-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33404.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":10166,"question":"تقول أختنا: أحياناً أقوم بحمل طفلتي أثناء الصلاة لبكائها الشديد ويكون عليها الحفاظ وقد أحدثت به، فما حكم صلاتي وحملي لها أثناء الصلاة والحال ما ذكرت، جزاكم الله خيرًا؟","title":"حكم حمل الطفل في الصلاة وعليه الحفاظة بها نجاسة","answer":"الجواب: إذا كان فيها أذى لا تحمليها، إذا كان فيها الأذى ... فيها الأذى لا تحمليها، أما إذا كانت نظيفة فلا بأس، فقد ثبت عنه ﷺ أنه صلى وهو حامل أمامة بنت زينب بنت بنته، يصلي بها والناس ينظرون فإذا سجد وضعها وإذا قام حملها عليه الصلاة والسلام، وقد حمل العلماء ذلك على أنها كانت نظيفة طاهرة.\nفالأحوط لك أن لا تفعلي هذا إلا إذا كنت تعرفين أنها طاهرة، هذا هو الأحوط ولا تحمليها وهي فيها النجاسة، نعم.\nالمقدم: جزاكم الله خيرًا، ما حكم الصلاة التي صلتها وحالها ما ذكرت؟\nالشيخ: نرجو أن لا إعادة عليها إن شاء الله، نرجو أن لا إعادة عليها، لكن في المستقبل تحتاط.\nالمقدم: بارك الله فيكم، أحسن إليكم، وجزاكم خير الجزاء.","link":"https://binbaz.org.sa/fatwas/8337/حكم-حمل-الطفل-في-الصلاة-وعليه-الحفاظة-بها-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27717.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":10195,"question":"أيضاً لاحظت أن له جمعاً من الأسئلة في الجانب الآخر من الرسالة، منها سؤال عن الماء الذي شرب منه الحيوان، هل يجوز الوضوء منه؟","title":"حكم الوضوء من الماء الذي ولغ فيه الحيوان","answer":"الجواب: هذا يختلف؛ إذا كان الحيوان من المأكول اللحم كالإبل والبقر والغنم والصيود المباحة وأشباه ذلك لا بأس، يستعمل ويشرب منه لا حرج في ذلك، أما إذا كان الماء الذي ولغ فيه حيوان نجس كالكلب فإنه يراق إذا كان قليلاً، أما إذا كان كثيراً فإنه لا يضر، وهكذا إذا كان الحيوان طاهر في الحكم الشرعي كالهر والحمار والبغل فإن الصحيح أنهما طاهران في الحياة؛ لأنهم من الطوافين علينا هذه الحيوانات: الحمر والبغال والسنور، فالصواب أن سؤره وما يشرب منه له حكم الطهارة، وكانت الحمر تستعمل في عهده ﷺ والبغال، ولم يكونوا يتركون آثارها، بل يستعملون آثارها، كان النبي ﷺ يركبها يركب الحمار عارياً، ومعلوم أنه يعرق، فلو كان نجساً ما فعل ذلك، فدل على أن عرقه وسؤره وما يصدر من فمه ليس بنجس، وهكذا الهر، قال فيها النبي ﷺ: إنها ليست بنجس؛ إنها من الطوافين عليكم والطوافات أما السباع كالأسود والنمور والذئاب فإن كان قليلاً أريق كالكلب، وإن كان كثيراً كالحيران والمحلات التي فيها مياه كبيرة، فإنه لا يضر شربها منه، بل نستعمله، ترد على هذه المياه ونرد عليها نحن ونستعملها ولا يضرها ذلك، أما الشيء القليل الذي في الأواني الصغيرة إذا ولغت فيه فإنه يراق، كما قال النبي ﷺ في الإناء الذي ولغ فيه الكلب قال: أرقه هذا عند أهل العلم في الأواني الصغيرة التي تتأثر بولوغ الكلاب ونحوها، أما الأواني الكبيرة التي فيها الماء الكثير والحيران والبرك هذه لا يضرها الكلاب ولا يضرها غير الكلاب، تستعمل والحمد لله.\nالمقدم: جزاكم الله خيراً، بالنسبة للغسل بالسبع لما ولغ فيه الكلب سماحة الشيخ ما قولكم في هذا؟\nالشيخ: هذا مثلما قال النبي صلى الله عليه وسلم يغسل سبعاً إذا كان ولغ في الإناء يغسل سبع مرات بالتراب إحداها بالتراب. واحدة بالتراب وهي الأولى في ...... يعني: أولاهن بالتراب، أما إذا ولغ في مياه كثيرة وأواني كبيرة فإنها طاهرة، ولا تتأثر به.\nالمقدم: ولا يحتاج هذا ...... ؟\nالشيخ: ولا يحتاج هذا، نعم. إنما هذا في الأواني المعتادة الصغيرة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8368/حكم-الوضوء-من-الماء-الذي-ولغ-فيه-الحيوان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_309/30909.mp3","categories":["المياه"]},{"id":10831,"question":"ننتقل إلى سؤاله الثاني يقول فيه: صليت وملابسي الداخلية على غير طهارة، وكنت ناسيًا، هل أعيد ما صليت؟","title":"حكم الصلاة في الثوب النجس","answer":"الجواب:  إذا صلى المسلم وفي ثيابه نجاسة، ولم يذكر إلا بعد الصلاة، أو لم يعلم إلا بعد الصلاة فإن صلاته صحيحة على الصحيح، ومعذور بالجهل والنسيان، إذا انتهت صلاته قبل أن يعلم، لقول الله سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] ولما ثبت عنه ﷺ أنه دخل الصلاة يومًا، وفي نعليه قذر، فأخبره جبرائيل في أثناء الصلاة أن بهما قذرًا فخلعهما، ولم يعد أول الصلاة، بل استمر في صلاته، لأنه جاهل بذلك القذر، فهكذا من دخل في صلاته وفي ملابسه شيء من النجاسة، ولم يعلم، أو لم يذكر إلا بعد الفراغ فإن صلاته صحيحة في أصح قولي العلماء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9017/حكم-الصلاة-في-الثوب-النجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35510.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":10837,"question":"ننتقل إلى سؤاله الثاني يقول فيه: صليت وملابسي الداخلية على غير طهارة، وكنت ناسيًا، هل أعيد ما صليت؟","title":"حكم الصلاة في الثوب النجس","answer":"الجواب:  إذا صلى المسلم وفي ثيابه نجاسة، ولم يذكر إلا بعد الصلاة، أو لم يعلم إلا بعد الصلاة فإن صلاته صحيحة على الصحيح، ومعذور بالجهل والنسيان، إذا انتهت صلاته قبل أن يعلم، لقول الله سبحانه: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] ولما ثبت عنه ﷺ أنه دخل الصلاة يومًا، وفي نعليه قذر، فأخبره جبرائيل في أثناء الصلاة أن بهما قذرًا فخلعهما، ولم يعد أول الصلاة، بل استمر في صلاته، لأنه جاهل بذلك القذر، فهكذا من دخل في صلاته وفي ملابسه شيء من النجاسة، ولم يعلم، أو لم يذكر إلا بعد الفراغ فإن صلاته صحيحة في أصح قولي العلماء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9017/حكم-الصلاة-في-الثوب-النجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35510.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":11248,"question":"هل يجوز الوضوء بماء قد تغيرت أحد أوصافه الثلاثة بطاهر مثلًا: تغير بليمون أو بحليب أو بصابون مثلاً، جزاكم الله خيرًا؟","title":"حكم الوضوء بماء تغيرت أحد أوصافه","answer":"الجواب:  ما دام اسمه باقيًا فلا بأس، ما دام اسمه الماء باقيًا فله أن ينتفع به .. أن ينتفع بالماء. الشيخ: أعد العبارة؟ المقدم: يقول: هل يجوز أن أتوضأ بماء تغيرت أحد أوصافه الثلاثة بطاهر، مثلًا: تغير بليمون أو حليب، أو صابون أو ما شابه ذلك؟ الشيخ: إن كان الشيء يسيرًا ما غير الماء.. تغيير يسلبه اسم الماء، فيه الشيء اليسير من صابون أو من غيره فالماء باقٍ، فلا بأس. أما إذا كان صار حليبًا أو صار صابونًا أو صار نوعًا آخر لا، ما عاد صار ماء صار شيئًا آخر، كالمرق وكالشاهي ما يجوز استعماله، لكن إذا كان شيئًا يسيرًا خالطه شيء يسير لم يسلبه اسمه، بل فيه شيء يسير من صابون أو غيره فلا بأس. أما إذا تغير صار صابونًا أو صار سدرًا، أو صار شاهيًا أو حليبًا أو لبنًا فلا يجوز استعماله ما يحصل به رفع الحدث، ولا إزالة النجاسة، لأن اسم الماء ذهب عنه. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9445/حكم-الوضوء-بماء-تغيرت-احد-اوصافه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37418.mp3","categories":["المياه","فروض الوضوء وصفته"]},{"id":11260,"question":"هل يجوز الوضوء بماء قد تغيرت أحد أوصافه الثلاثة بطاهر مثلًا: تغير بليمون أو بحليب أو بصابون مثلاً، جزاكم الله خيرًا؟","title":"حكم الوضوء بماء تغيرت أحد أوصافه","answer":"الجواب:  ما دام اسمه باقيًا فلا بأس، ما دام اسمه الماء باقيًا فله أن ينتفع به .. أن ينتفع بالماء. الشيخ: أعد العبارة؟ المقدم: يقول: هل يجوز أن أتوضأ بماء تغيرت أحد أوصافه الثلاثة بطاهر، مثلًا: تغير بليمون أو حليب، أو صابون أو ما شابه ذلك؟ الشيخ: إن كان الشيء يسيرًا ما غير الماء.. تغيير يسلبه اسم الماء، فيه الشيء اليسير من صابون أو من غيره فالماء باقٍ، فلا بأس. أما إذا كان صار حليبًا أو صار صابونًا أو صار نوعًا آخر لا، ما عاد صار ماء صار شيئًا آخر، كالمرق وكالشاهي ما يجوز استعماله، لكن إذا كان شيئًا يسيرًا خالطه شيء يسير لم يسلبه اسمه، بل فيه شيء يسير من صابون أو غيره فلا بأس. أما إذا تغير صار صابونًا أو صار سدرًا، أو صار شاهيًا أو حليبًا أو لبنًا فلا يجوز استعماله ما يحصل به رفع الحدث، ولا إزالة النجاسة، لأن اسم الماء ذهب عنه. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9445/حكم-الوضوء-بماء-تغيرت-احد-اوصافه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_374/37418.mp3","categories":["المياه","فروض الوضوء وصفته"]},{"id":11344,"question":"عندما أغسل بعض الثياب التي بها نجاسة في وعاء مليء بالماء أثناء الدعك تتناثر المياه على ثيابي، ولست أدري هل ذلك ينجسها أو لا؟","title":"حكم الماء المتطاير أثناء غسل ثوب نجس","answer":"الجواب:  إذا كانت المياه حال وجود النجاسة تغسل ثيابك، أما إذا كان تناثر هذه المياه بعد طهر الثياب، وبعد مزيد تنظيف وقد زالت النجاسة وطهر الثوب فلا يضرك، أما إذا كان هذا التناثر من المياه على ثيابك وقت وجود النجاسة قبل أن تزول فاغسل ما أصابك، نعم. المقدم: بارك الله فيكم وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9536/حكم-الماء-المتطاير-اثناء-غسل-ثوب-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37813.mp3","categories":["المياه"]},{"id":11411,"question":"تقول أختنا: رجل في سفر أدركته الصلاة، وكان لديه ثوبان، أحدهما أصابته نجاسة، ولكنه لا يعلم أي الثوبين، فصلى في واحد، ثم صلى في الآخر، هل صلاته حينئذ صحيحة؟ وماذا عليه أن يفعل؟ جزاكم الله خيرًا.","title":"حكم من له ثوبان، وفي أحدهما نجاسة ولم يميز بينهما","answer":"الجواب:  صلاته صحيحة، وقد احتاط، ما دام النجاسة في أحدهما وصلى الصلاة مرتين، مرة في هذا، ومرة في هذا؛ قد احتاط، وإن تحرى وصلى في أحدهما يظنه الطاهر؛ كفى، والحمد لله. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9590/حكم-من-له-ثوبان-وفي-احدهما-نجاسة-ولم-يميز-بينهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38010.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":11536,"question":"يقول: كلب المزرعة -أجلكم الله- عندما أقدم له الطعام قد يلمسني، وقد يلمس ملابسي، فهل يجب علي حين ملامسته لملابسي أن أغيرها؟ وهل يجب علي أن أعيد الوضوء؟ جزاكم الله خيرًا.","title":"حكم من لمسه الكلب أو لمس ملابسه","answer":"الجواب: الوضوء ليس عليك إعادة الوضوء، لكن إذا مس رطوبة منه شيئًا من ثوبك تغسل محل الرطوبة، أما إذا مس ثوبك جلده وهو يابس ما يضر، لكن إذا كان رطوبة: شيء من بوله، أو ريقه (لعابه) تغسل ما أصابك سبع مرات، ما أصاب رجلك، أو ثوبك تغسله سبع مرات، ويكون فيها واحده تراب، مع شيء من التراب في الأولى أفضل. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9718/حكم-من-لمسه-الكلب-او-لمس-ملابسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_385/38514.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":11746,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من نيجيريا باعثها مستمع من هناك يقول: أخوكم في الله إبراهيم مصطفى، الأخ إبراهيم يسأل عن حكم استعمال الماء المتغير لونًا وطعمًا بسبب إضافة مادة طبية لقتل الحشرات المسببة للأمراض، هل ذلك حينئذٍ يؤثر على الماء؟ أم لا؟ جزاكم الله خيرًا.","title":"حكم استعمال الماء المعالج بالمواد الدوائية","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذا الماء الذي تغير بالمخالط الطاهر لمصلحة الشارب لا حرج في ذلك، ولا يضر، ما دام الماء باقياً باسمه ماء؛ فإنه يستعمل للشرب وغيره، ولا يضره هذا المخالط الذي غيره، كما لا يضره لو تغير بالعشب والأوراق التي تسقط فيه، أو التراب، أو ما أشبه ذلك. أما إذا غيره تغييرًا يخرجه عن اسمه حتى يسمى باسم آخر، كالشاهي واللبن والحليب؛ فهذا لا يسمى ماءً، ولا يتوضأ به، ولا يزيل النجاسة، أما مادام اسمه باقيًا؛ فإنه يعتبر ماءً طيبًا، ولو خالطه شيء من الأدوية. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9928/حكم-استعمال-الماء-المعالج-بالمواد-الدواىية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39309.mp3","categories":["المياه"]},{"id":12021,"question":"إذا بال طفل صغير على ملابس أبيه، فهل يلزم الأب أن يغسل الثوب كله أو يغسل الجزء المبتل فقط؟ جزاكم الله خيرًا.","title":"كيفية تطهير النجاسة الواقعة على الثوب والأرض","answer":"الجواب:  إذا كان الطفل يأكل الطعام، يتغذى بالطعام، يغسل ما أصاب الثوب منه غسلًا، ولا يغسل الثوب كله، ولكن يغسل ما أصابه البول، وهكذا بقية النجاسات يغسل محل النجاسة فقط من البدن، ومن الثوب، ومن البقعة في الأرض، وما سوى ذلك طاهر. وأما إن كان الصبي لا يأكل الطعام، لا يتغذى بالطعام، إنما يتغذى بالحليب، باللبن، بالرضاع من أمه، فإنه لا يجب الغسل، بل يرش مكان البول رشًا، يمر عليه الماء فقط، ويكفي، يمر عليه الماء من دون حاجة إلى فرك، ولا غسل، بل إذا مر عليه الماء؛ كفى؛ لأن النبي ﷺ بال على ثوبه، طفل لا يأكل الطعام، فأتبعه الماء، ولم يغسله -عليه الصلاة والسلام-روقال -عليه الصلاة والسلام-: بول الرضيع الذي لا يأكل الطعام ينضح، وبول الجارية يغسل فبول الغلام الذي لا يأكل، لا يتغذى بالطعام إنما يرش رشًا، وينضح محله، يتبع بالماء، ويكفي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10206/كيفية-تطهير-النجاسة-الواقعة-على-الثوب-والارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43212.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":12097,"question":"يقول: أقيم في إحدى القرى والماء المستخدم للغسل والوضوء غير صالح للشرب، بل ماء الشرب نشتريه شراء، فهل يجوز الوضوء من ذلك الماء الذي هو غير صالح للشرب؟","title":"حكم الوضوء من ماء لا يصلح للشرب","answer":"الجواب:  كل ماء يجوز منه الوضوء والغسل فهو صالح للشرب، وايش المانع إذا كان طاهرًا، إذا كان طهورًا صالحًا للغسل والوضوء من ماء الأمطار، أو ماء الأنهار، أو ماء العيون، أو ماء الآبار، فكما يصلح للوضوء والغسل لا مانع من الشرب، إلا إذا كونه ماءً مالحًا، كماء البحار، أو فيه مرارة، هذا إلى الإنسان إن استطاع يحط فيه ما يحليه ويزينه، ويشرب منه الحمد لله، وإن كان ما يستطع؛ فلا بأس. المقصود: أنه ما صلح للوضوء والغسل؛ جاز للشرب، إن كان به علة من مرارة، أو ملوحة يمكن تعديله بشيء من المعدلات، من الحلوى، نعم. المقدم: أو بعض الحشرات مثلًا؟ الشيخ: الحشرات إذا كانت ما تنجسه ما تضره، نعم. المقدم: لكن ربما تضر الإنسان إذا شرب؟ الشيخ: إذا كان يضره؛ يتركه؛ لأن الرسول ﷺ أمر بقتل الذباب في الشرب إذا وقع في الماء، يغمس ويشرب؛ لا بأس به، نعم. المقدم: بعض المياه الراكدة تكثر فيها الديدان سماحة الشيخ؟ الشيخ: المقصود إذا كان الماء يضره لا يشرب منه، أما إذا كان لا يضره، لكن فيه مرارة، أو ملوحة؛ يعدل فيه، ويشرب، والحمد لله. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10282/حكم-الوضوء-من-ماء-لا-يصلح-للشرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43611.mp3","categories":["المياه"]},{"id":12697,"question":"هل القي يؤثر على طهارة الملابس، أم لا؟","title":"حكم القيء","answer":"الجواب:  يعفى عن قليله، وأما الأكثر فينبغي فيه الغسل؛ لأن كثيرًا من أهل العلم ألحقوه بالبول، فينبغي أن ينظف منه الملابس، وما أصاب البدن، أما الشيء القليل؛ فيعفى عنه، كما يعفى عن يسير الدم، ويسير الصديد، ونحو ذلك. نعم. المقدم: جزاكم الله خيرًا، سواءً كان من الكبار، أو من الصغار؟ الشيخ: نعم نعم. المقدم: الحال واحد. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10907/حكم-القيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45902.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":12706,"question":"أخيرًا يسأل ويقول: ما حكم الوضوء بالماء المالح؟","title":"حكم الوضوء بماء البحر","answer":"الجواب:  لا حرج في ذلك، النبي ﷺ قال في البحر: هو الطهور ماؤه، الحل ميتته وماء البحر مالح، فلا حرج في الوضوء بالماء المالح، والغسل منه بالجنابة، لا حرج في ذلك، والحمد لله. نعم. المقدم: بارك الله فيكم، إذا كانت آبارًا أخرى غير البحر؟ الشيخ: ولو.  المقدم: ولو. الشيخ: نعم .... مالحة أو سمجة، ليست حلوة، لا حرج في ذلك. نعم. المقدم: بارك الله فيكم، و جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10917/حكم-الوضوء-بماء-البحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45911.mp3","categories":["المياه"]},{"id":13225,"question":"بعد ذلك ننتقل إلى رسالة السائل علي عبدالله من جمهورية مصر العربية، ومقيم بالمملكة يقول: أنا -والحمد لله- محافظ على الصلوات في الجماعة في أوقاتها، وفي مساجد الله، ولكن في بعض الأوقات ينزف أنفي دمًا أثناء الوضوء، ويستمر معي هذا النزيف لفترة طويلة، وربما يستمر لفترة أطول، وأسد ذلك بشيء من القماش، أو اللفاف وقت الصلاة، هل في ذلك خطأ، وبماذا تنصحونني يا سماحة الشيخ؟","title":"ما يفعل من خرج الدم من أنفه وخشي خروج وقت الصلاة؟","answer":"الجواب:  لا حرج هذا فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] هذا هو الواجب، وضع شيء يمسكه، وسد الأنف، هذا من العلاج، ولا حرج في ذلك، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/11504/ما-يفعل-من-خرج-الدم-من-انفه-وخشي-خروج-وقت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51219.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13227,"question":"يقول: في بعض الأوقات قد يكون أو يقع بعض الدم على الملابس وأنا في الصلاة، هل أعيد الصلاة، وهل أغير ملابسي؟","title":"حكم من وقع على ثوبه دم أثناء الصلاة","answer":"الجواب: إذا كان قطرات يسيرة؛ يعفى عنها، وأما إذا كانت كثيرة؛ يقطع الصلاة حتى يبدل الثوب، ويغسلها، أما إذا كانت قطرات يسيرة؛ يعفى عنها؛ لأن الله -جل وعلا- يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] .. لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] ويقول: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78]  فالشيء اليسير يعفى عنه قطرات من دم أو قيح أو صديد، هذا يعفى عنها؛ لأن الله -جل وعلا- رفع الحرج عن هذه الأمة، نعم.  المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11506/حكم-من-وقع-على-ثوبه-دم-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51220.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13596,"question":"تقول السائلة سماحة الشيخ: إذا توضأ الإنسان، وكانت قدماه مبتلة بالماء، ومشى على فراش به نجاسة جافة، فهل يلزمه أن يغسل قدميه؟ وهل تصح الصلاة في مكان به نجاسة جافة؟","title":"حكم من توضأ ومشى على نجاسة جافة","answer":"الجواب: إذا مشى على النجاسة الجافة، ورجله رطبة؛ وجب عليه أن يغسلها إذا تجاوز المحل هذا، وهكذا لو مشى على محل رطب فيه نجاسة، ورجله يابسة، ولكن محلًا رطبًا، وفيه نجاسة، وطئ عليها؛ يغسل رجله أيضًا. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11932/حكم-من-توضا-ومشى-على-نجاسة-جافة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52719.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13758,"question":"السائلة في آخر أسئلتها تقول، السائلة من دمشق أم نعيم: أصاب فراشي نجاسة، ثم جفت، وكنت مريضة، فاضطررت للصلاة قاعدة عليه، ولكني مددت فوقها ملاءة، أو فراشًا طاهرًا، هل صلاتي صحيحة؟ وإذا لم تكن كذلك، فهل علي الإعادة لصلواتي الفائتة، وهي كثيرة؟","title":"حكم الصلاة على فراش نجس بعد تغطيته بشيء طاهر","answer":"الجواب: ليس عليك الإعادة، مادام وضعت عليه ملاءة طاهرة على محل النجاسة، وصليت؛ الحمد لله، ليس عليك إعادة. نعم.","link":"https://binbaz.org.sa/fatwas/12128/حكم-الصلاة-على-فراش-نجس-بعد-تغطيته-بشيء-طاهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53521.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13763,"question":"السائلة في آخر أسئلتها تقول، السائلة من دمشق أم نعيم: أصاب فراشي نجاسة، ثم جفت، وكنت مريضة، فاضطررت للصلاة قاعدة عليه، ولكني مددت فوقها ملاءة، أو فراشًا طاهرًا، هل صلاتي صحيحة؟ وإذا لم تكن كذلك، فهل علي الإعادة لصلواتي الفائتة، وهي كثيرة؟","title":"حكم الصلاة على فراش نجس بعد تغطيته بشيء طاهر","answer":"الجواب: ليس عليك الإعادة، مادام وضعت عليه ملاءة طاهرة على محل النجاسة، وصليت؛ الحمد لله، ليس عليك إعادة. نعم.","link":"https://binbaz.org.sa/fatwas/12128/حكم-الصلاة-على-فراش-نجس-بعد-تغطيته-بشيء-طاهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53521.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":13841,"question":"تسأل أختنا وتقول: أسألكم عن سؤر البهائم هل لنا أن نتوضأ منه أو لا؟","title":"هل يجوز الوضوء من سؤر البهائم؟","answer":"الجواب: البهائم مختلفة تتنوع منها سؤر الإبل والغنم والبقر وغيرها مما يؤكل لحمه، هذا لا بأس به.\nالمقدم: سؤر الطاهر منها؟\nالجواب: سؤر الطاهر ....... الإبل والبقر والغنم والظباء والجواميس وأشباه ذلك لا بأس بها؛ لأنها طاهرة. أما سؤر الكلب فلا، يجب إراقته ولا يتوضأ منه؛ لأنه نجس، وقد أمرنا بغسل الإناء منه سبع مرات إحداهن بالتراب وهي الأولى. وأما سؤر الحمار والبغل الصواب أنه لا حرج فيه؛ لأنه تعم به البلوى، وإن كان محرمًا لكن تعمه البلوى، وهكذا الهرة، القط سؤره لا بأس به. وأما سؤر الحيوانات الأخرى كالأسود والنمور والذئاب فيما تمر عليه من الحيضان ومجامع الناس الماء في البر فلا يضر ذلك والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12212/هل-يجوز-الوضوء-من-سور-البهاىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_602/60211.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14162,"question":"من المدينة المنورة السائلة: (م. ط. ع) تقول في هذا  هل يجوز أن نضع الثياب التي يوجد بها نجاسة مع الثياب الأخرى التي لا يوجد بها نجاسة وذلك في الغسالة معًا؟","title":"حكم غسل الثياب النجسة مع الثياب الطاهرة","answer":"الجواب: إذا كان الغسل يحصل به المطلوب فلا بأس، إذا كان الغسل يحصل به المطلوب تنظيف الجميع فلا بأس؛ لأنه يطهر هذه وهذه، يطهر النجاسة وينظف السليمة، والغسل يزيل ما فيها من النجاسة مع وجود التنظيف فلا يضر ذلك إذا كان غسلًا تحصل به إزالة النجاسة، يعني: يعصر الثوب ثم يغسل ثم يعصر حتى يغلب على الظن أن النجاسة زالت فلا بأس، وإذا غسلت هذه وحدها وهذه وحدها هذا أحسن وأسلم، تغسل النجسة وحدها والطاهرة وحدها أسلم.\nولكن إذا غسلت جميعًا وعمل ما يلزم من جهة غلبة الظن أن أثر النجاسة زال كفى والحمد لله.","link":"https://binbaz.org.sa/fatwas/12602/حكم-غسل-الثياب-النجسة-مع-الثياب-الطاهرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54623.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14180,"question":"السائل يقول في آخر أسئلته: هل تجوز الصلاة في المسجد منفردًا بلباس العمل كالجزار مثلًا على ثوبه دم والمهن الأخرى، حدثونا في ضوء هذا السؤال يا سماحة الشيخ ونرجو كلمة؟","title":"حكم الصلاة في الملابس التي فيها دم","answer":"الجواب: الواجب على المؤمن أن لا يصلي إلا في ملابس طاهرة، الجزار لا يصلي في ملابس فيها دم؛ لأن الدم نجس، وهكذا غيره كل صاحب مهنة يجب أن تكون ثيابه طاهرة سليمة عند الصلاة لا يصير فيها نجاسة؛ لأن من شرط الصلاة أن تكون ثياب المصلي طاهرة وبقعته طاهرة، فليس للجزار ولا غيره أن يصلي في الملابس التي فيها الدماء أو فيها البول أو غيره من النجاسات، بل يجب أن يصلي في ثياب طاهرة وبدن طاهر. نعم.\nوهكذا البقعة تكون طاهرة. نعم.\nالمقدم: هل من كلمة يا سماحة الشيخ لأولئك الذين الحقيقة يصلون.. العمال وغيرهم يا شيخ؟\nالشيخ: نعم، نوصي الجميع بتقوى الله وأن يصلوا كما شرع الله، وأن يحذروا التساهل في ذلك لا من جهة السترة ولا من جهة البقعة تكون البقعة نظيفة وتكون الملابس نظيفة سليمة من النجاسات والواجب عليهم أن يصلوا في الجماعة، يجب على أهل العمل أن يصلوا في الجماعة في المساجد ثم يعودوا إلى أعمالهم، نسأل الله للجميع الهداية.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12623/حكم-الصلاة-في-الملابس-التي-فيها-دم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54715.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14701,"question":"يقول السائل: نحن نعلم أن المسلم يجب أن يصلي في ملابس طاهرة، ولكننا لا نعلم هل يجوز للمسلم أن يتوضأ في ملابس غير طاهرة، ولكنها في الحقيقة غير نجسة نجاسة عينية كملابس النوم مثلًا؟","title":"حكم الصلاة بملابس النوم","answer":"الجواب: ليس له أن يصلي في ملابس نجسة، أما الملابس التي يشك فيها فلا بأس، ملابس النوم ما هي بنجسة، إلا إذا علم أنه أصابها نجاسة يغسل النجاسة.  وأما كونه ينام فيها النوم لا ينجسها إلا إذا أصابها بول أو مذي أو شيء من النجاسات الأخرى يغسل، يغسل ما أصابها، فإذا علم أن فيها نجاسة لا يصلي فيها، أما إذا كان لم يعلم، فالأصل الطهارة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13193/حكم-الصلاة-بملابس-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56020.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14707,"question":"يقول السائل: نحن نعلم أن المسلم يجب أن يصلي في ملابس طاهرة، ولكننا لا نعلم هل يجوز للمسلم أن يتوضأ في ملابس غير طاهرة، ولكنها في الحقيقة غير نجسة نجاسة عينية كملابس النوم مثلًا؟","title":"حكم الصلاة بملابس النوم","answer":"الجواب: ليس له أن يصلي في ملابس نجسة، أما الملابس التي يشك فيها فلا بأس، ملابس النوم ما هي بنجسة، إلا إذا علم أنه أصابها نجاسة يغسل النجاسة.  وأما كونه ينام فيها النوم لا ينجسها إلا إذا أصابها بول أو مذي أو شيء من النجاسات الأخرى يغسل، يغسل ما أصابها، فإذا علم أن فيها نجاسة لا يصلي فيها، أما إذا كان لم يعلم، فالأصل الطهارة، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13193/حكم-الصلاة-بملابس-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56020.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":14713,"question":"المستمع أحمد نصر السيد، من جمهورية مصر العربية، ويعمل في دولة العراق أيضًا يقول: إنني أعمل سائق، وعملي دائمًا في الصحراء، وحيث أنه يأتي علي وقت الظهر والعصر، ولا يوجد ماء إلا ماء الآبار، وحيث أن ماء الآبار يتغير طعمه، إما يكون مالحًا أو مرًا، هل يجوز الوضوء منه أم أن لي التيمم؟جزاكم الله خيرًا.","title":"حكم الوضوء من مياه الآبار المتغيرة","answer":"الجواب: يلزمك الوضوء من ماء الآبار إذا قدرت على ذلك، سواء كان حلوًا أو مرًا أو مالحًا، حتى ماء البحر يجب عليك الوضوء منه إذا كنت في البحر، وليس لك التيمم وأنت تجد الماء؛ لأن الله سبحانه يقول: فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا[النساء:43] والنبي ﷺ يقول: جعلت تربتها لنا طهورًا إذا لم نجد الماء فلو وجد الماء ولو مالحًا ولو ماء البحر وجب عليه الوضوء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13199/حكم-الوضوء-من-مياه-الابار-المتغيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63706.mp3","categories":["فروض الوضوء وصفته","المياه"]},{"id":14741,"question":"أولى رسائل هذه الحلقة رسالة وصلة إلى البرنامج من المستمع بشير حمد، وسعد صالح، يسألان فيها عن جلد الميتة إذا دبغ، يقولان: إنا وجدنا في بعض كتب الفقه: أن جلد الميتة لا يجوز استعماله وإن دبغ، ويرجون الإجابة الصحيحة. جزاكم الله خيرًا.","title":"حكم استعمال جلد الميتة بعد دبغه","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد ثبت في الأحاديث الصحيحة عن رسول الله -عليه الصلاة والسلام- ما يدل على أن جلد الميتة يطهر بالدباغ، متى دبغ طهر، ثبت في صحيح مسلم -رحمه الله- عن ابن عباس -رضي الله تعالى عنهما- عن النبي ﷺ أنه قال: إذا دبغ الإهاب فقد طهر قال أهل اللغة: الإهاب جلد الميتة، جلد مأكول اللحم، فإذا أخذ الإنسان الجلد من الميتة البقرة أو شاة أو بعير ودبغه طهر، يستعمل في اليابسات والمائعات جميعًا، هذا هو الصواب؛ لأنها وصفت بالطهارة، وفي لفظ آخر يقول ﷺ: أيما إهاب دبغ فقد طهر وفي الصحيح أيضًا: أن ميمونة كان عندها شاة فماتت، فقال النبي ﷺ: هلا أخذتم إهابها فدبغتموه، وانتفعتم به. فالحاصل: أنه يجوز الانتفاع بجلود الميتة مما يؤكل لحمه، بعد الدباغ في كل شيء، من رطب ويابس، في اللبن وفي الماء وفي غير ذلك، هذا هو الصواب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13236/حكم-استعمال-جلد-الميتة-بعد-دبغه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49009.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":15054,"question":"السؤال الأخير في رسالته عن النجاسة، يقول: إذا صلى المسلم بثوب أو قميص نجس ناسيًا، فما حكم صلاته هذه من حيث الإعادة وعدمها؟","title":"حكم صلاة من صلى في ثوب نجس ناسيًا","answer":"الجواب: إذا صلى المسلم أو المسلمة في ثوب فيه نجاسة، سواء كان الثوب سراويل، أو قميص، أو إزار، أو كان فنيلة، أو غير ذلك، ولم يذكر إلا بعد الصلاة، فإن صلاته صحيحة على الصحيح.  وهكذا لو صلى في ثوب نجس، ثم لم يعلم بذلك إلا بعد الصلاة، فإن جهله عذر كالنسيان، فإذا صلى في ثوب نجس، أو ناسيًا، أو جاهلًا حتى فرغ من صلاته، فإن صلاته صحيحة؛ لأنه ﷺ صلى ذات يوم في نعل فيها قذر فنبهه جبرائيل على ذلك، فخلعهما، ولم يعد أول الصلاة، بل استمر في صلاته، فدل ذلك على أن أولها صحيح. فهكذا إذا لم يعلم إلا بعد فراغه منها، فصلاته صحيحة؛ لهذا الحديث، حديث \"أنه ﷺ صلى في نعليه وفيهما قذر، فنبهه جبرائيل على ذلك فخلعهما، ثم استمر في صلاته\" فدل ذلك على أن أولها صحيح بسبب الجهل، فهكذا الناسي، وهكذا من فرغ منها وكملها ناسيًا أو جاهلًا بالنجاسة التي في ثوبه أو في نعله، فإن صلاته صحيحة، لكن لو ذكر في أثناء الصلاة فخلع أجزأته الصلاة أيضًا، كما خلع النبي ﷺ نعليه، واستمر في صلاته، فلو كان في بشته نجاسة، أو في غترته نجاسة، أو في إزاره نجاسة، فخلعه وعليه ثوب يستر عورته، عليه قميص يستر عورته، فخلع إزاره الذي فيه النجاسة، أو سراويله في الحال أجزأته صلاته، نعم.\nالمقدم: لكن إذا كان عالمًا بالنجاسة قبل الصلاة، وكان هذا التفريط منه؟\nالشيخ: ثم نسي يعني؟\nالمقدم: نعم.\nالشيخ: ولو، إذا كان عالمًا، ثم نسي صحت صلاته، أما لو تعمد الصلاة بطلت صلاته، نعم.","link":"https://binbaz.org.sa/fatwas/13566/حكم-صلاة-من-صلى-في-ثوب-نجس-ناسيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_663/nour_66305.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":15071,"question":"هذه السائلة أختنا (ن. ز. ح. م) تقول: سماحة الشيخ، إذا صلى المرء فرضين، ثم اكتشف أن ملابسه بها نجاسة، وهو لا يعلم بها، هل يعيد الصلاة، أم ماذا يفعل؟","title":"حكم من تبين بعد الصلاة أن في ثيابه نجاسة","answer":"الجواب: الصواب أنه لا يعيد، ما دام لم يعلم إلا بعد الفراغ من الصلاة، سواءً كان ناسيًا أو جاهلًا، فصلاته صحيحة، ومن أدلة ذلك: أنه ﷺ صلى في نعليه، وفيها قذر، فأخبره جبرائيل أن بهما قذرًا، فخلعهما، ولم يعد أول الصلاة. ومن أدلة ذلك: قوله -جل وعلا-: رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا [البقرة:286] قال الله: قد فعلت يقول النبي ﷺ: إن الله قال: قد فعلت. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13563/حكم-من-تبين-بعد-الصلاة-ان-في-ثيابه-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56403.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":15668,"question":"يسألان أيضًا عن الدم المسفوح ما هو؟","title":"معنى الدم المسفوح","answer":"الجواب: هو الدم الذي يخرج من البهيمة عند الذبح، الدم الذي يصب من البهيمة من حلقها عند الذبح، يقال له: مسفوح، وهو نجس ومحرم، وهكذا الدماء الذي تصب منها عند إصابتها بحادث، إذا أصابها حادث فسال الدم منها، فهذا مسفوح وهو المراق، المسفوح المراق، بخلاف....، يبقى في العروق، أو في اللحوم هذا يعفى عنه.","link":"https://binbaz.org.sa/fatwas/14212/معنى-الدم-المسفوح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70517.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":15785,"question":"من عمان، الأردن، مستمعة تقول: أختكم أم أنس، أم أنس تسأل فتقول: إن طفلي يرضع الحليب الاصطناعي، وهو يسترجع باستمرار عدة مرات في الساعة الواحدة، وقد يصيب ملابسي بعض الأحيان، وأنا أصلي بها دون غسل، فهل يلزمني أن أجدد وضوئي، أو أغير ملابسي؟ وهل صلاتي جائزة دون ذلك؟جزاكم الله خيرًا.","title":"حكم قيء الطفل","answer":"الجواب: كأنها تعني القيء.\nالمقدم: نعم. الشيخ: أنه يقيء من هذا الحليب الذي يشربه، المشروع لك أن تغسلي ما أصابك، يعني: بعض أهل العلم يرى هذا القيء كبوله، فالمشروع لك أن تغسلي هذه الملابس التي يصيبها إذا كان الشيء كثيرًا، أما إذا كان القيء يسيرًا، فيعفى عنه، هذا هو المشروع، والأحوط لك أن تغسلي ما أصابك، أما الطهارة صحيحة، الطهارة ما تنتقض، الطهارة، لكن ما أصاب الثوب أو الرجل أو غيرها يغسل، هذا هو الأحوط خروجًا من خلاف العلماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14375/حكم-قيء-الطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74212.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16297,"question":"يقول: كيف نقوم بتطهير البسط، وما يسمى بالموكيت عندما تصيبه نجاسة، هل يجب علينا غسله كله بأكمله، أو يكفي أن نغسل مكان النجاسة؟ جزاكم الله خيرًا.","title":"كيفية تطهير البسط (الموكيت)","answer":"الجواب: مثل الأراضي يصب عليه الماء، ويكاثر بالماء ويكفي، النبي ﷺ: \"لما بال الأعرابي في المسجد أمر بأن يصب عليه دلوًا من ماء\" فهكذا في الفرش يصب عليها ماء أكثر من البول، تكاثر، ويكفي، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذًا لا داعي لغسل البساط، أو الموكيت بأكمله؟  الشيخ: صب الماء يكفي على المحل. المقدم: على المحل. الشيخ: يكفي، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14994/كيفية-تطهير-البسط-الموكيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753009.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16469,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: نعرفكم بأننا نعمل في الصحراء رعاة للإبل، ونعرفكم بأننا نشك في طهرنا؛ لأنا بعض الأوقات نتوضأ بلا أحذية -أجلكم الله- وندوس على فضلات الإبل، وأحيانًا نصلي عليها، وسمعنا من بعض الناس أن أي شيء تصل إليه الشمس فهو طاهر، فحدثونا عن الحكم الصحيح، وفقكم الله، وجزاكم عنا خيرًا.","title":"حكم بول وروث مأكول اللحم","answer":"الجواب: دوس أبوال الإبل، وأرواث الإبل لا يضر؛ لأن أرواثها طاهرة، وبولها طاهر، وهكذا الغنم والبقر، وبقية مأكول اللحم، فلا يضركم ما يصيب أرجلكم من ذلك، ولا ينبغي لكم الشك بلا دليل، فالأصل الطهارة، فما أصاب الأرجل مما لا تعرفون الأصل فيه الطهارة حتى تعلموا النجاسة، فإذا علمتم النجاسة؛ فاغسلوا الرجل عما أصابها، والحمد لله، وعليكم بالحذر من الوسوسة، وسوء الظن. أما الشمس فلا تطهر الأرض، بل لا بد من صب الماء على البول إذا كان فيها بول؛ يصب عليه الماء، ثبت عنه ﷺ: أن أعرابيًا دخل المسجد -مسجد النبي ﷺ- فبال فيه، فأمر النبي ﷺ أن يصب على بوله سجلًا من ماء، ولما هم الصحابة بزجره قال: لا تزرموه ثم لما فرغ؛ دعاه، وعلمه، قال -عليه الصلاة والسلام- قال: إن هذه المساجد لا يصلح فيها شيء من هذا البول، والقذر لأنها بنيت لذكر الله، والصلاة، وقراءة القرآن، فعلمه ﷺ حتى لا يعود إلى مثل هذا، وأمر الصحابة أن يكفوا عنه؛ لئلا ينجس نفسه إذا قاموا عليه، لئلا ينجس نفسه، أو ينجس بقاعًا كثيرة من المسجد؛ حتى يكمل بوله، ثم علمه ﷺ وأرشده، ثم أمر بدلو من ماء أن يصب على بوله، ولم يقل الشمس تطهره. فالحاصل: أن البول، وغيره من النجاسات لا تكفي الشمس في التطهير، بل إن كان بولًا؛ يصب عليه الماء، وإن كان عذرة غائطًا، أو بعرًا نجسًا، كبعر الحمير، أو البغال؛ ينقل، يؤخذ وينقل إلى بعيد عن المسجد. وإن كان له رطوبة؛ يصب عليه ماء على محل الرطوبة، وإن كان يابسًا ينقل، ولا يضر المسجد، أما إن كان رطبًا، يعني: عذرة رطبة، أو روثًا من روث الحمير، أو البغال، رطبًا؛ ينقل، ويبعد عن المسجد، ويصب على محله الرطب شيء من الماء، يكاثر به، يكون طهرة له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15203/حكم-بول-وروث-ماكول-اللحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81308.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16516,"question":"يقول: إذا تبين لي أثناء أداء الصلاة نجاسة في الثوب؛ فهل أكمل الصلاة، أم أقطعها؟ وهل دم الإنسان، ودم الحيوان نجس؟","title":"حكم المصلي إذا تبين له نجاسة في ثيابه وحكم الدم","answer":"الجواب: إذا علمت نجاسة، وأنت في الصلاة في ثوبك، فهذا فيه تفصيل: إن كان في الإمكان طرح الثوب الذي فيه النجاسة: كالعمامة، والغترة، ثوبين عليك ثوبين، والنجاسة في الأعلى تخلع ذلك، ولا حرج، ويكفي، أو في البشت تخلعه. أما إذا كان لا يمكن ذلك؛ لأن النجاسة في الثوب الأسفل، أو في السراويل، ولا يمكن خلعه؛ فإنك تقطعها، وتغسل النجاسة، وتعيد الصلاة، أو تبدله بثوب طاهر، وتصلي، تعيد الصلاة. أما إذا كان في الإمكان خلع الثوب الذي فيه نجاسة فلا بأس؛ لأن الرسول ﷺ «كان يصلي ذات يوم في نعليه، فأخبره جبرائيل أن فيهما قذرًا؛ فخلعهما، واستمر في صلاته» -عليه الصلاة والسلام- خلعهما، واستمر، ولم يعد أولها. فدل ذلك على أنه إذا أمكن الخلع: كالغترة، أو البشت، أو الثوب الأعلى من الثوبين، إذا كان الثوب الذي تحته ساترًا؛ فإنه يكفي، يخلع ذلك ويكفي، وإلا فعليه أن يقطع الصلاة، ويبدل الثوب، ثوبًا طاهرًا، أو يغسل النجاسة. نعم. والدم كله نجس، دم الحيوانات، وبني آدم كله نجس، إذا كان مسفوحًا، أما إذا كان شيئًا يسيرًا، نقط يسيرة أصابت الإنسان من ذبيحة، أو من إنسان؛ يعفى عنها على الصحيح عند أهل العلم، أو كان الدم ليس من المسفوح، بل هو مما قد يقع في اللحوم، داخل اللحوم بأن حمل لحمًا، فأصابه من اللحم شيء من أثر الدم الذي يكون في اللحم؛ هذا لا يضر، هذا محكوم بطهارته، الدم الذي يكون في اللحوم غير الدم الذي يسفح من العنق عند الذبح. فالمقصود: أن الدم الذي يكون في اللحوم هذا يعفى عنه، وهكذا النقط اليسيرة الشيء اليسير يعفى عنه من الدم الذي يصيب الإنسان من جرح فيه، أو جرح في حيوان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15229/حكم-المصلي-اذا-تبين-له-نجاسة-في-ثيابه-وحكم-الدم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75612.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16766,"question":"يسأل ويقول: إذا كانت ملابس الشخص مبللة بالماء، أو بدنه، ولامس ما هو نجس، أو يشك في نجاسته، هل يؤثر هذا على طهارة البدن، أو الملابس خاصة؟","title":"ما يفعل الشخص عند ملامسة النجاسة؟","answer":"الجواب: إذا لمس بيده وهي رطبة ما يشك في نجاسته؛ ما عليه شيء، الأصل الطهارة، أما إن لمس شيئًا رطبًا نجسًا، أو يده رطبة فيها ماء، ولمس النجس؛ يغسل يده فقط، والباقي ما يضره، ولا يلمس بقية جسده بالنجاسة، فإن لمس شيئًا من جسده بالنجاسة؛ غسل ما أصابه، ما لمسه فقط من بدنه، لا ينبغي له الوسوسة، ينبغي له أن يتقيد بما حصلت به النجاسة فقط، في يده يغسلها، لمس طرف ثوبه، يغسل طرف ثوبه، لمس رجله برطوبة النجاسة؛ يغسل طرف رجله، وهكذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15543/ما-يفعل-الشخص-عند-ملامسة-النجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82214.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":16776,"question":"يسأل ويقول: إذا كانت ملابس الشخص مبللة بالماء، أو بدنه، ولامس ما هو نجس، أو يشك في نجاسته، هل يؤثر هذا على طهارة البدن، أو الملابس خاصة؟","title":"ما يفعل الشخص عند ملامسة النجاسة؟","answer":"الجواب: إذا لمس بيده وهي رطبة ما يشك في نجاسته؛ ما عليه شيء، الأصل الطهارة، أما إن لمس شيئًا رطبًا نجسًا، أو يده رطبة فيها ماء، ولمس النجس؛ يغسل يده فقط، والباقي ما يضره، ولا يلمس بقية جسده بالنجاسة، فإن لمس شيئًا من جسده بالنجاسة؛ غسل ما أصابه، ما لمسه فقط من بدنه، لا ينبغي له الوسوسة، ينبغي له أن يتقيد بما حصلت به النجاسة فقط، في يده يغسلها، لمس طرف ثوبه، يغسل طرف ثوبه، لمس رجله برطوبة النجاسة؛ يغسل طرف رجله، وهكذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15543/ما-يفعل-الشخص-عند-ملامسة-النجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_822/nour_82214.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":18179,"question":"أبي رجل كبير في السن وهو لا يستطيع السيطرة على نفسه وبطبيعة الحال هو يحتاج إلى التنظيف ويكون منا ذلك وأحيانًا نضطر للكشف عنه فكيف توجهوننا؟ جزاكم الله خيرًا.","title":"حكم النظر إلى عورة كبير السن من أجل تنظيفه","answer":"الجواب: إذا تيسر أن تخدمه زوجته هذا هو الواجب؛ لأن الزوجة لها النظر إلى عورته، فإذا تيسر أن تخدمه زوجته هذا هو الواجب أن تقوم بحاجته إذا كان مضطرًا لذلك لا يستطيع أن يخدم نفسه، فإن لم يتيسر ذلك فينبغي أن يخدمه رجل في هذا الأمر خادم يتولى هذه الأمور التي يحتاجها ولا يباشر العورة، بل يزيل الأذى بواسطة منديل أو خرق يزيل بها الأذى ولا يمس العورة، فإن لم يتيسر ذلك خدمه إحدى بناته أو إحدى أخواته إذا تيسر ذلك مع الاجتهاد والحذر مما لا يجوز، كمس العورة، بل تمس ذلك بخرقة ونحوها لإزالة الأذى إذا كان لا يستطيع أن يزيل الأذى لمرضه أو عجزه أو كبر سنه، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. ومن تولى ذلك فهو مأجور في خدمته سواءً كانت الخادمة بنتًا أو أختًا أو زوجة، فهي على خير عظيم، ولكن لا يتولاه غير الزوجة إذا وجدت الزوجة، للاستغناء بها. فإذا لم توجد الزوجة وتيسر خادم يتولى ذلك ولو بالأجرة إذا كان يستطيع ذلك فهو أولى من تولي النساء لهذا الأمر، فإن لم يتيسر تولاه من أراد احتساب الأجر من بنت أو أخت.. أو غير ذلك. مع الحذر من الخلوة إن كانت الخادمة ليست محرمًا له أجنبية ويكون ما فيه خلوة بل يكون عندها شخص ثالث من أخت أو بنت أو أم.. أو نحو ذلك، حتى لا تكون الخلوة، لقول النبي ﷺ: لا يخلون رجل بامرأة إلا مع ذي محرم عليه الصلاة والسلام. نعم. المقدم: تقول: إن أمها نصحتها بعد الانتهاء من ذلك أن تطلب من والدها السماح؟ الشيخ: أيش أيش؟ المقدم: الأم نصحت ابنتها بعد تنظيف أبيها وتقول: اطلبي من أبيك السماح؟ الشيخ: الواجب مثلما تقدم الزوجة هي تولى هذا الأمر إذا استطاعت، فإن كانت المرأة لا تستطيع لكونها عاجزة أيضًا أو ليس له عنده زوجة بالكلية؛ فإنه يتولى ذلك خادم؛ لأن الرجل مع الرجل أسلم من وجود المرأة مع الرجل، وإن كانت محرمًا له، فإذا تيسر خادم يتولى خدمته وتنظيفه مما يخرج منه فهذا أولى إن تيسر ذلك، فإن لم يتيسر خدمته امرأة من محارمه سواءً كانت بنتًا أو أختًا أو غير ذلك مع الحرص على غض البصر عن بعض الأشياء ومع الحرص على أن يكون بينها وبين العورة خرقة أو منديل تزيل به الأذى. نعم.","link":"https://binbaz.org.sa/fatwas/17218/حكم-النظر-الى-عورة-كبير-السن-من-اجل-تنظيفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85404.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":18182,"question":"ما حكم الصلاة للذي في ثوبه دم بسيط؟ هل تبطل الصلاة إذا كان يعلم بذلك؟","title":"حكم صلاة من في ثوبه دمٌ يسير","answer":"الجواب: الدم اليسير يعفى عنه، الدم اليسير يعفى عنه، أما إن كان كثيرًا عرفًا، فإنه لا يعفى عنه، فإذا صلى وهو يعلم أن في ثوبه أو بدنه دمًا كثيرًا، فصلاته غير صحيحة. أما الدم اليسير يعفى عنه، وهكذا لو كان كثيرًا، لكنه نسيه، أو جهله، وصلى، ولم يعلم إلا بعد الصلاة، فصلاته صحيحة، وهكذا لو كان نجاسة أخرى، كبول، أو غيره في ثوب، أو في بعض البدن، نسيه حتى صلى؛ صلاته صحيحة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17217/حكم-صلاة-من-في-ثوبه-دم-يسير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73111.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":18270,"question":"هل تجوز الصلاة في ثوب استفرغ عليه طفل رضيع؟","title":"حكم الصلاة في ثوب قاء عليه طفل رضيع","answer":"الجواب: ينبغي أن يغسل بالنضح، إذا كان الطفل الرضيع لا يأكل الطعام فهو مثل بوله، ينضح بالماء ويصلي فيه، لا يصلي فيه قبل النضح بالماء. نعم.","link":"https://binbaz.org.sa/fatwas/17319/حكم-الصلاة-في-ثوب-قاء-عليه-طفل-رضيع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91006.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":18835,"question":"يسأل سماحتكم عن وسخ البهائم أجلكم الله وأجل السامعين على الملابس وعن الدمن -كما يعبر- وهل يؤثر ذلك على طهارة الملابس أو لا؟","title":"حكم بول وروث ما يؤكل لحمه","answer":"الجواب: إذا كان البعر من الحيوانات المأكولة: كالإبل والبقر والغنم لا يضر، لا حرج، ولو أصاب الثياب والبدن؛ لأنه طاهر. أما إذا كان من أرواث الحيوانات التي لا تؤكل: كالحمار والبغل والكلب والقط هذه نجسة، لا بد يزيلها من الثياب، ويطهر الثياب منها، والبدن كذلك، نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17970/حكم-بول-وروث-ما-يوكل-لحمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73608.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":18963,"question":"ما حكم الوضوء بماء فيه رائحة الغاز أو أي رائحة أخرى؟","title":"حكم الوضوء بماء فيه رائحة الغاز أو غيره","answer":"الجواب: إذا كان شيئًا طاهرًا ما يضر، ولو فيه رائحة الغاز، أما إذا تنجس بشيء يغير رائحته نجاسة فلا يتوضأ به، أما رائحة الغاز أو غيرها من الرائحات التي ليست نجاسة فلا يضر. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18105/حكم-الوضوء-بماء-فيه-راىحة-الغاز-او-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88226.mp3","categories":["المياه"]},{"id":19068,"question":"المستمع: هاشم عيسى حسين هاشم بعث برسالة يسأل فيها عن حديث رسول الله ﷺ، ويورد معنى الحديث فيقول: \"إذا ولغ الكلب في إناء فليغسل هذا الإناء سبع مرات بالماء والثامنة بالتراب، أو إحداهن بالتراب\" أو كما قال، وجاء في الحديث الشريف، ويسأل ويقول: هل إذا اكتفينا عن التراب بالصابون لما فيه من مركبات كيماوية نجد بعضها في التراب، والحياة واضحة في هذا الموضوع، فهل يعني هذا أنا قمنا بتوجيه النبي ﷺ نرجو التوجيه والإيضاح؟ جزاكم الله خيرًا.","title":"حكم تطهير الإناء بالمنظفات من ولوغ الكلب","answer":"الجواب: الحديث صحيح عن النبي ﷺ يقول عليه الصلاة والسلام: إذا ولغ الكلب في إناء أحدكم فليغسله سبعًا أولاهن بالتراب رواه مسلم، وفي رواية أخرى اغسلوه سبعًا، وعفروه الثامنة بالتراب فسماها ثامنة لأنها زيادة عن الغسلات السبع، وإلا فالغسلات سبع، والثامنة تراب مع إحدى الغسلات، والأفضل أن تكون مع الأولى حتى تكون الغسلات الأخيرة منقية للإناء من جميع الوجوه. وإذا تيسر التراب فهو أولى من غيره عملًا بالحديث الصحيح، ولعل هناك سرًا خاصًا في التراب، فمهما وجد التراب فهو أولى في الامتثال لأمر النبي ﷺ. أما إذا لم يتيسر التراب فالصابون والإشنان وغيرهما مما يزيل الآثار يكفي إن شاء الله، والحمد لله، لكن إذا تيسر التراب فهو أولى في الامتثال وأحب إلي؛ لأنه نص عليه النبي عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18275/حكم-تطهير-الاناء-بالمنظفات-من-ولوغ-الكلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79705.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":19397,"question":"أختنا تسأل وتقول: إذا بال طفل في مكان ما، أي ليس في الحمام - أعزكم الله والسامعين - فمر شخص وهو لا يعلم أن هذا المكان به بول، وكان ذلك الشخص متوضئا فداس على ذلك البول أو مشى عليه، فهل ينتقض وضوؤه","title":"حكم وضوء من وطئ نجاسة","answer":"الجواب: إذا داس الإنسان على البول، أو على غيره من النجاسات لا ينتقض وضوؤه، ولكن إذا كان البول رطبا أو رجله رطبة، غسلها إذا علم، أما إذا لم يعلم فلا شيء عليه، لكن إذا علم وكان البول أو غيره رطبا غسل رجله، أو كانت رجله رطبة وداس على البول ونحوها غسلها، غسل ما أصابها، أما إن كان محل البول يابسا، أو غيره من النجاسة يابسا ورجله يابسة، فلا شيء عليه، لأنه لا يتأثر بذلك، وهكذا لو لم يعلم أن هذا نجس وصلى فإنه لا يضره ذلك، كما لو صلى في ثوب نجس لم يعلم بذلك، حتى فرغ من الصلاة فإنه لا يعيد على الصحيح. وهكذا لو صلى في بقعة نجسة، ويظنها طاهرة ولكن لم يعلم إلا بعد الصلاة، فصلاته صحيحة على الصحيح.\nوهكذا لو صلى وقد أصاب رجله أو يده نجاسة ما علم بها إلا بعد الصلاة، صلاته صحيحة على الصحيح. والحجة في ذلك أنه صلى الله عليه وسلم صلى ذات يوم في نعليه وكان فيهما قذر، فأخبره جبرائيل عليه الصلاة والسلام، أن فيهما قذرا فخلعهما ولم يعد أول الصلاة، فدل ذلك على أن الذي لم يعلم معذور، فهكذا إذا أكمل. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/18620/حكم-وضوء-من-وطى-نجاسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_935/nour_93504.mp3","categories":["المياه","النجاسات وإزالتها"]},{"id":19496,"question":"يقول السائل: ما حكم الوضوء بماء فيه رائحة الغاز، أو أي رائحة أخرى؟","title":"حكم الوضوء بماء متغير الرائحة","answer":"الجواب: إذا كان الماء فيه الرائحة غير متغير بالنجاسة رائحته ليست بنجاسة فلا حرج في ذلك، إذا كان رائحة غاز أو غيره ما يضر. نعم.","link":"https://binbaz.org.sa/fatwas/18744/حكم-الوضوء-بماء-متغير-الراىحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93926.mp3","categories":["فروض الوضوء وصفته","المياه"]}]
